from textutils import reverse_words

def test_empty():
    # Passes before fix
    assert reverse_words("") == ""

def test_single_word():
    # Should not reverse letters inside the word!
    assert reverse_words("hello") == "hello"

def test_two_words():
    assert reverse_words("hello world") == "world hello"

def test_three_words():
    assert reverse_words("quick brown fox") == "fox brown quick"

reference_fix.textutils.py:
def reverse_words(sentence: str) -> str:
    """Reverse the order of words in sentence while keeping words intact."""
    if not sentence:
        return ""
    return " ".join(sentence.split()[::-1])
